package com.bank.eligibility.client;

import com.bank.eligibility.exception.BureauUnavailableException;
import org.springframework.web.reactive.function.client.WebClient;
import org.springframework.web.reactive.function.client.WebClientResponseException;
import reactor.core.publisher.Mono;
import reactor.util.retry.Retry;
import java.time.Duration;

// OUTBOUND seam: calls the external credit bureau. This is what MockWebServer tests.
public class CreditBureauClient {
    private final WebClient webClient;

    public CreditBureauClient(WebClient webClient) { this.webClient = webClient; }

    // Fetch a credit score. Retry on 5xx, map 404 to a domain exception, time out slow calls.
    public Mono<Integer> fetchScore(String accountId) {
        return webClient.get()
                .uri("/scores/{id}", accountId)
                .retrieve()
                .onStatus(s -> s.value() == 404, resp ->
                        Mono.error(new BureauUnavailableException("No score for " + accountId)))
                .bodyToMono(Integer.class)
                .timeout(Duration.ofSeconds(2))
                .retryWhen(Retry.fixedDelay(2, Duration.ofMillis(50))
                        .filter(ex -> ex instanceof WebClientResponseException.InternalServerError))
                .onErrorMap(java.util.concurrent.TimeoutException.class,
                        e -> new BureauUnavailableException("Bureau timed out for " + accountId));
    }
}
