package com.bank.eligibility.service;

import com.bank.eligibility.client.CreditBureauClient;
import com.bank.eligibility.dto.*;
import reactor.core.publisher.Mono;

public class EligibilityService {
    private final CreditBureauClient bureau;
    public EligibilityService(CreditBureauClient bureau) { this.bureau = bureau; }

    public Mono<EligibilityResponse> evaluate(EligibilityRequest req) {
        return bureau.fetchScore(req.getAccountId())
                .map(score -> new EligibilityResponse(req.getAccountId(),
                        score >= 700 ? "APPROVED" : "REJECTED", score));
    }
}
