package com.bank.eligibility.client;

import com.bank.eligibility.exception.BureauUnavailableException;
import okhttp3.mockwebserver.*;
import org.junit.jupiter.api.*;
import org.springframework.web.reactive.function.client.WebClient;
import reactor.test.StepVerifier;
import java.io.IOException;

// MockWebServer: a REAL local HTTP server standing in for the credit bureau.
class CreditBureauClientTest {
    private MockWebServer server;
    private CreditBureauClient client;

    @BeforeEach void setUp() throws IOException {
        server = new MockWebServer();
        server.start();
        client = new CreditBureauClient(WebClient.create(server.url("/").toString()));
    }

    @AfterEach void tearDown() throws IOException { server.shutdown(); } // MUST shut down

    @Test void retriesOnServerErrorThenSucceeds() throws InterruptedException {
        // Script: first 500 (should be retried), then a good 200 with the score.
        server.enqueue(new MockResponse().setResponseCode(500));
        server.enqueue(new MockResponse().setResponseCode(200)
                .setHeader("Content-Type", "application/json").setBody("760"));

        StepVerifier.create(client.fetchScore("SAV2001"))
                .expectNext(760)
                .verifyComplete();

        // Assert the OUTBOUND request we actually sent — the whole point of MockWebServer.
        RecordedRequest first = server.takeRequest();
        Assertions.assertEquals("GET", first.getMethod());
        Assertions.assertEquals("/scores/SAV2001", first.getPath());
    }

    @Test void mapsNotFoundToDomainException() {
        server.enqueue(new MockResponse().setResponseCode(404));
        StepVerifier.create(client.fetchScore("UNKNOWN"))
                .expectError(BureauUnavailableException.class)
                .verify();
    }

    @Test void timesOutOnSlowBureau() {
        server.enqueue(new MockResponse().setResponseCode(200).setBody("700")
                .setBodyDelay(5, java.util.concurrent.TimeUnit.SECONDS)); // slower than 2s timeout
        StepVerifier.create(client.fetchScore("SAV2001"))
                .expectError(BureauUnavailableException.class)
                .verify(java.time.Duration.ofSeconds(4));
    }
}
