package com.bank.eligibility.controller;

import com.bank.eligibility.dto.*;
import com.bank.eligibility.service.EligibilityService;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.reactive.WebFluxTest;
import org.springframework.boot.test.mock.mockito.MockBean;
import org.springframework.http.MediaType;
import org.springframework.test.web.reactive.server.WebTestClient;
import reactor.core.publisher.Mono;

// WebTestClient + @WebFluxTest: drive OUR controller in-memory, service mocked.
@WebFluxTest(EligibilityController.class)
class EligibilityControllerTest {

    @Autowired WebTestClient webTestClient;
    @MockBean EligibilityService service;   // collaborator stubbed, not the real bureau

    @Test void validRequestReturns200WithDecision() {
        Mockito.when(service.evaluate(Mockito.any()))
               .thenReturn(Mono.just(new EligibilityResponse("SAV2001", "APPROVED", 760)));

        webTestClient.post().uri("/api/v1/eligibility")
                .contentType(MediaType.APPLICATION_JSON)
                .bodyValue("{\"accountId\":\"SAV2001\",\"loanAmount\":500000}")
                .exchange()
                .expectStatus().isOk()
                .expectBody()
                .jsonPath("$.status").isEqualTo("APPROVED")
                .jsonPath("$.score").isEqualTo(760);
    }

    @Test void missingAccountIdReturns400() {
        // Validation failure — tests OUR routing/validation, no downstream involved.
        webTestClient.post().uri("/api/v1/eligibility")
                .contentType(MediaType.APPLICATION_JSON)
                .bodyValue("{\"loanAmount\":500000}")
                .exchange()
                .expectStatus().isBadRequest();
    }
}
